#' Estimate and correct edge effect for each screen plate
#'
#' This function subtracts the incubation (or edge) effect from the observed
#' signal intensity to recover the true signal intensity. If the incubation
#' effect has already been estimated by \code{fitEdgeEffect()} function,
#' the values in the edgeFactor column will be used. Otherwise, this function
#' will first call \code{fitEdgeEffect()} function to estimate the edge effect.
#'
#' @param screenData a data frame containing screening results generated by
#' \code{readScreen()} function. In order for the edge effect estimate algorithm
#' to work, plate normalization needs to be performed first.
#' @param estimateMethod a character string specifying the method used for
#' estimating the shape and strength of edge effect. Currently two methods are
#' supported: 'loess', which uses a local regression model to estimate edge effect;
#' 'sigmoid', an experimental feature, which uses use a 2D-sigmoid model to
#' estimate edge effect. The "loess" method is suitable for both regular
#' incubation effect, such as edge effect, and irregular incubation effect.
#' But sometimes it tends to over-smooth the edge effect when the edge effect
#' is rectangular. In this case, "sigmoid" method can better capture the shape
#' of edge effect. But the "sigmoid" method can not deal with incubation effect
#' with irregular shape.
#' @param useNeg a logical value. If TRUE, only negative controls are used to
#' estimate edge effect. Otherwise, all the wells are used for edge effect
#' estimation.
#' @param useLowConcentrations a integer value. In addition to negative controls,
#' sample wells with low concentrations of compounds can be considered as
#' 'de facto' negative controls and included in edge effect estimation.
#' The default value is 0, means no sample wells are used. If the value n >= 1,
#' the n lowest concentrations will be used.
#' @param span a numeric value. The span parameter for \code{loess} method,
#' which controls the degree of smoothing. Values are typically between 0 and 1, 
#' though values larger than 1 are accepted, the larger the value, the smoother 
#' the fitted curve. The default value is 1.
#' @param correctMethod a character string specifying the method used for
#' adjusting the edge effect. Currently two methods 'bliss' and 'linear' are
#' supported.
#' If \code{bliss} is selected, the corrected values are simply the normalized
#' signal intensity values divided by the estimated incubation/edge effect
#' intensity.
#' If \code{linear} is selected, the correction process will be smoothed by a
#' linear function depending on the original normalized signal intensity. This
#' option is suitable for the situation when the edge effect is very strong
#' and results in instability in the correction process.
#' @param exclude a list of samples that should be excluded when performing
#' edge effect correction
#' @export
#' @import dplyr
#' @return This function will add one column, \code{normVal.cor}, which is the
#' normalized viability corrected for incubation/edge effect, to the input data
#' frame.
#' @examples
#' # load drug screen dataset
#' data('screenData_normalized')
#' screenData_corrected <- correctEdgeEffect(screenData_normalized,
#'                                           estimateMethod = 'loess',
#'                                           useNeg = TRUE,
#'                                           useLowConcentrations = 0,
#'                                           span =1,
#'                                           correctMethod = 'bliss')

correctEdgeEffect <- function(screenData,
                              estimateMethod = "loess",
                              useNeg = TRUE,
                              useLowConcentrations = 0L,
                              span = 1,
                              correctMethod = "bliss",
                              exclude = c()) {

  # Input validation
  if (span <= 0 || is.na(span) || !is.numeric(span)) {
    stop("span must be a positive numeric value")
  }
  checkmate::assert_choice(estimateMethod, c("loess", "sigmoid"))
  checkmate::assert_choice(correctMethod, c("bliss", "linear"))
  checkmate::assert_logical(useNeg, len = 1, any.missing = FALSE)
  checkmate::assert_number(useLowConcentrations, lower = 0, finite = TRUE)
  checkmate::assert_data_frame(screenData, any.missing = TRUE, 
                                min.rows = 1, min.cols = 1)
  checkmate::assert_names(names(screenData), must.include = c("sampleID", "fileName", 
                            "wellType", "normVal"))
# Warning if span > 1
  if (span > 1) {
    warning("Span value is greater than 1. This may result in over-smoothing of the edge effect estimation. Please ensure that this is the intended behavior.")
  }
  # argument match
  estimateMethod <- match.arg(estimateMethod, c("loess", "sigmoid"))
  correctMethod  <- match.arg(correctMethod, c("bliss", "linear"))

  # Update exclusion list if 'sampleID' column exists
  if ("sampleID" %in% colnames(screenData)) {
    exclude <- unique(c(exclude, screenData %>%
                          dplyr::filter(sampleID %in% exclude) %>%
                          dplyr::pull(fileName)))
  }

  if (!"edgeFactor" %in% colnames(screenData)) {
    # edge effect estimation hasn't been performed. Estiamte the edge effect first
    screenData <- fitEdgeEffect(screenData,
                                method = estimateMethod,
                                useNeg = useNeg,
                                useLowConcentrations = useLowConcentrations,
                                span = span,
                                exclude = exclude)
  }

  if (correctMethod == "bliss") {
    screenData <- dplyr::mutate(screenData, normVal.cor = normVal/edgeFactor)
  }

  if (correctMethod == "linear") {
    screenData <-
      dplyr::mutate(screenData,
                    normVal.cor = corEdgeLinear(normVal, edgeFactor))
  }

  return(screenData)
}





